INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Clearly trivial threshold application
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinecrest Manufacturing, the engagement team sets overall materiality at $200,000 and identifies a $350 misstatement in office supplies expense. Under AU-C 450, misstatements that are clearly trivial are those that:', '["Are individually or in aggregate well below any amount that could influence user decisions", "Fall below 5% of overall materiality regardless of their nature", "Are limited to income statement accounts and do not affect the balance sheet", "Have already been corrected by management before year-end"]'::jsonb, 0, 'AU-C 450.A2 defines clearly trivial misstatements as those well below any amount that could be consequential to users, whether judged individually or in aggregate. The auditor need not accumulate such items. Option B is incorrect because AU-C 450 does not prescribe a fixed 5% threshold — the determination is based on professional judgment, not a mechanical percentage.', 'medium', 2),

-- Q2: medium / L2 — Fraud-related misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'While auditing Redstone Financial Group, the senior auditor discovers a $4,200 journal entry that a staff accountant recorded without supporting documentation to meet a quarterly revenue target. Under AU-C 450, the auditor should treat a misstatement arising from fraud differently from one arising from error because:', '["Fraud-related misstatements require immediate notification to law enforcement before further audit procedures", "The auditor must apply a higher materiality threshold to fraud misstatements than to error misstatements", "A misstatement arising from fraud is not necessarily inconsequential even when the amount is small, due to its intentional nature", "Fraud-related misstatements must always be reported as material weaknesses under AU-C 265"]'::jsonb, 2, 'AU-C 450.A5 states that a misstatement arising from fraud is not necessarily inconsequential even if the dollar amount is small, because fraud may indicate a more pervasive problem. The intentional nature elevates the auditor''s concern about management integrity. Option A is incorrect because AU-C 450 does not require immediate law enforcement notification — the auditor''s response depends on the circumstances and applicable legal requirements.', 'medium', 2),

-- Q3: medium / L3 — Iron curtain vs rollover approach
(1, 'Misstatements and Control Deficiencies', 'Thornfield Corporation has a $45,000 uncorrected misstatement that originated in 2024 and carries over to 2025. Using the rollover approach, the auditor evaluates only the current-year effect of $5,000 and concludes it is immaterial. Under AU-C 450.06, the auditor should also consider:', '["Whether the cumulative balance-sheet effect of the misstatement is material to the current period financial statements", "Whether the misstatement was disclosed in the prior-year management representation letter only", "Whether the rollover approach eliminates the need for further quantitative evaluation", "Whether the prior-year auditor issued an unmodified opinion on the financial statements"]'::jsonb, 0, 'AU-C 450.06 requires the auditor to consider both the current-period effect (rollover approach) and the cumulative effect on the balance sheet (iron curtain approach) when evaluating uncorrected misstatements. Relying solely on the rollover amount may understate the impact on the financial position. Option C is incorrect because the rollover approach alone is insufficient — the auditor must also evaluate the iron curtain perspective.', 'medium', 3),

-- Q4: easy / L1 — Definition of clearly trivial
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what is the meaning of "clearly trivial" in the context of audit misstatements?', '["Misstatements that are below the overall materiality level for the engagement", "Misstatements that management has already corrected before the audit report date", "Misstatements that are inconsequential whether judged individually or in aggregate", "Misstatements that affect only disclosure notes rather than financial statement line items"]'::jsonb, 2, 'AU-C 450.A2 establishes that clearly trivial misstatements are those inconsequential to users whether judged individually, in aggregate, or by any criteria of size, nature, or circumstance. The auditor is not required to accumulate such items. Option A is incorrect because clearly trivial is a much lower threshold than materiality — it represents amounts too small to warrant accumulation.', 'easy', 1),

-- Q5: medium / L3 — Prior-period misstatement effect on current opinion
(1, 'Misstatements and Control Deficiencies', 'During the 2025 audit of Bridgewater Logistics, the auditor discovers that a $130,000 misstatement from 2024 was never corrected and now affects the opening balance of retained earnings. Overall materiality for 2025 is $150,000. The auditor should evaluate whether:', '["The misstatement must be corrected before an unmodified opinion can be issued on the 2025 statements", "The prior-period misstatement affects the comparability and overall presentation of 2025 financial statements", "The misstatement can be ignored because it relates to a period already reported upon by another auditor", "The client must restate the 2024 financial statements before the 2025 audit can be completed"]'::jsonb, 1, 'AU-C 450.11 requires the auditor to evaluate prior-period uncorrected misstatements for their effect on the current period. A $130,000 carryover against $150,000 materiality significantly narrows the remaining tolerance for new misstatements and affects comparability. Option C is incorrect because prior-period misstatements remain relevant regardless of who performed the prior audit — their effect on current-year figures must be assessed.', 'medium', 3),

-- Q6: medium / L2 — Uncorrected misstatements in representation letter
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Maplewood Retail Corp., the auditor has accumulated $38,000 in uncorrected misstatements that management declines to adjust. Under AU-C 450.14, the auditor should obtain from management:', '["A revised engagement letter acknowledging the uncorrected misstatements and the auditor''s modified opinion", "A journal entry proposal for the uncorrected items to be posted in the subsequent period", "Written representations that management believes the uncorrected misstatements are immaterial individually and in aggregate", "An independent assessment from the audit committee confirming that the misstatements do not require correction"]'::jsonb, 2, 'AU-C 450.14 requires the auditor to request written representations from management acknowledging that uncorrected misstatements are immaterial, both individually and in the aggregate, to the financial statements as a whole. Option A is incorrect because uncorrected immaterial misstatements do not automatically require a modified opinion or a revised engagement letter.', 'medium', 2),

-- Q7: medium / L2 — IT general control deficiency cascading impact
(1, 'Misstatements and Control Deficiencies', 'During the audit of Evergreen Technologies, the auditor discovers that the company''s user access management system allows terminated employees to retain system access for up to 90 days. Under AU-C 265, the auditor evaluates this IT general control deficiency by considering:', '["Only the actual dollar amount of unauthorized transactions traced to terminated employees during the audit period", "Whether the deficiency could affect multiple application controls that rely on the access management system", "Whether the IT department has documented the 90-day policy in its procedures manual", "The total number of employees terminated during the year relative to total headcount"]'::jsonb, 1, 'AU-C 265.A8 requires the auditor to consider the breadth of impact when evaluating IT general control deficiencies. A weakness in access management is pervasive because it undermines the reliability of all application controls dependent on user access restrictions. Option A is incorrect because the evaluation must consider the potential magnitude, not just actual observed transactions — a deficiency may be severe even without detected misstatements.', 'medium', 2),

-- Q8: hard / L4 — Combined qualitative/quantitative factors for misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'Granite Peak Industries has $62,000 in uncorrected misstatements against $500,000 overall materiality. The misstatements are quantitatively immaterial. However, $18,000 relates to management bonus calculations, and $12,000 converts a small reported profit into a loss. The remaining $32,000 involves routine expense classification errors. The auditor should conclude that:', '["All misstatements are quantitatively immaterial and therefore require no further evaluation or opinion modification", "The qualitative characteristics of certain misstatements may render the aggregate material despite being below the quantitative threshold", "The routine classification errors must be excluded from the qualitative evaluation because they have no earnings impact", "The profit-to-loss conversion is irrelevant because the overall financial statements remain fairly presented"]'::jsonb, 1, 'AU-C 450.11 requires the auditor to consider both quantitative and qualitative factors when evaluating uncorrected misstatements. Misstatements affecting management compensation or converting profits to losses carry qualitative significance that may cause otherwise immaterial amounts to influence user decisions. Option A is incorrect because quantitative immateriality alone does not eliminate the need for qualitative analysis — the nature and context of misstatements matter.', 'hard', 4),

-- Q9: medium / L3 — Extrapolation of sample misstatements to population
(1, 'Misstatements and Control Deficiencies', 'While testing accounts receivable for Cascade Electronics, the auditor selects a statistical sample of 40 items from a population of 3,200 items totaling $1.6 million and finds $6,000 in misstatements. The auditor projects the likely misstatement to $480,000. Under AU-C 450, the auditor should next:', '["Immediately qualify the audit opinion because the projected misstatement exceeds a reasonable threshold", "Evaluate the projected misstatement together with other accumulated misstatements against overall materiality", "Request that management correct only the $6,000 in known misstatements found in the sample", "Expand the sample to 100% of the population to confirm the projected misstatement amount"]'::jsonb, 1, 'AU-C 450.05 requires the auditor to accumulate all identified misstatements, including projected misstatements from sampling, and evaluate them in the aggregate against materiality. The projected amount joins other misstatements in the summary schedule. Option C is incorrect because addressing only the known sample errors ignores the likely population-level impact that sampling was designed to estimate.', 'medium', 3),

-- Q10: medium / L2 — Communication timeline for control deficiencies
(1, 'Misstatements and Control Deficiencies', 'The audit of Silverline Properties was completed on March 15, 2026, with the audit report dated the same day. The auditor identified two significant deficiencies during fieldwork. Under AU-C 265.13, the written communication of significant deficiencies and material weaknesses should be made:', '["Before the audit report is issued so that those charged with governance can take corrective action", "No later than 60 days following the audit report release date", "Within 30 days of discovering each individual deficiency during the audit", "Only after management has had the opportunity to remediate the deficiencies"]'::jsonb, 1, 'AU-C 265.13 requires the auditor to communicate significant deficiencies and material weaknesses in writing no later than 60 days following the report release date. This timeline allows the auditor to complete the full evaluation before communicating. Option C is incorrect because the standard does not require communication within 30 days of discovery — the 60-day window runs from the report release date.', 'medium', 2),

-- Q11: easy / L1 — Adjusting entry vs reclassifying entry
(1, 'Misstatements and Control Deficiencies', 'In the context of audit misstatements, what is the difference between an adjusting entry and a reclassifying entry?', '["An adjusting entry corrects an error in amount or recognition, while a reclassifying entry moves amounts between line items", "An adjusting entry is proposed by the auditor, while a reclassifying entry is proposed by management", "An adjusting entry affects only the balance sheet, while a reclassifying entry affects only the income statement", "An adjusting entry requires audit committee approval, while a reclassifying entry does not"]'::jsonb, 0, 'AU-C 450.04 distinguishes between adjusting entries, which correct errors in measurement or recognition that affect account balances, and reclassifying entries, which correct presentation or classification without changing net income or total assets. Both types are accumulated during the audit. Option B is incorrect because either the auditor or management may propose both types of entries — the distinction is about the nature of the correction, not who proposes it.', 'easy', 1),

-- Q12: hard / L3 — Component misstatement aggregation in group audit
(1, 'Misstatements and Control Deficiencies', 'Westbrook Holdings has four subsidiaries audited by component auditors. The group auditor receives summaries of uncorrected misstatements: Component A ($35,000), Component B ($28,000), Component C ($42,000), and Component D ($15,000). Group materiality is $200,000 and component materiality was set at $80,000. Under AU-C 600, the group engagement partner should:', '["Accept each component''s conclusion that its misstatements are immaterial since all are below component materiality", "Disregard Components A and D because their misstatements are below 25% of component materiality", "Aggregate all component misstatements and evaluate the combined $120,000 against group materiality", "Require each component auditor to reperform testing because uncorrected misstatements indicate audit deficiencies"]'::jsonb, 2, 'AU-C 600.A60 requires the group engagement partner to evaluate the aggregate effect of uncorrected misstatements from all components against group materiality. The $120,000 total (60% of group materiality) requires careful consideration even though each component''s misstatements are individually below component materiality. Option A is incorrect because component-level immateriality does not address the cumulative group-level effect.', 'hard', 3),

-- Q13: medium / L2 — Pervasiveness concept for deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Oakdale Pharmaceuticals, the auditor identifies a control deficiency in the monthly journal entry review process. The review is the sole control over manual journal entries across all financial statement accounts. Under AU-C 265, the pervasiveness of a control deficiency refers to:', '["The total dollar amount of misstatements that resulted from the deficiency during the audit period", "The number of financial statement accounts, disclosures, or assertions potentially affected by the deficiency", "The length of time the deficiency has existed without remediation by management", "The organizational level of the person responsible for the deficient control"]'::jsonb, 1, 'AU-C 265.A12 indicates that pervasiveness is a key factor in severity evaluation, referring to how many accounts, disclosures, or assertions could be affected. A deficiency in journal entry review is highly pervasive because manual entries touch virtually all accounts. Option A is incorrect because pervasiveness concerns the scope of potential impact, not the actual dollar amount of detected misstatements.', 'medium', 2),

-- Q14: hard / L4 — Multi-year unremediated deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'Crescent Valley Bank reported a significant deficiency in loan loss reserve estimation to its audit committee in both 2024 and 2025. For the 2026 audit, the auditor observes that management has still not remediated the deficiency, and this year a $340,000 misstatement was detected in the reserve (materiality: $400,000). The auditor should evaluate whether:', '["The deficiency should be downgraded to a lesser classification because its existence has been previously communicated", "Management''s failure to remediate over multiple years, combined with the current-year misstatement magnitude, indicates the deficiency has become a material weakness", "The significant deficiency classification should remain unchanged because no misstatement has actually exceeded materiality", "The prior-year communications satisfy the current-year reporting obligation and no new letter is needed"]'::jsonb, 1, 'AU-C 265.A7 requires reassessment of deficiency severity each period. Management''s persistent failure to remediate, combined with a misstatement at 85% of materiality, indicates increasing risk that a material misstatement could occur and not be prevented or detected. The pattern elevates the deficiency toward material weakness. Option C is incorrect because severity depends on reasonable possibility, not on whether a misstatement has already exceeded materiality — the trend and proximity indicate escalating risk.', 'hard', 4),

-- Q15: medium / L2 — Segregation of duties deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Coastal Marine Supply, the auditor finds that the accounts payable clerk both processes invoices and approves payments up to $10,000. Total annual payments processed by this individual approximate $2.8 million. Under AU-C 265, this segregation of duties deficiency should be evaluated based on:', '["Only the $10,000 per-transaction approval limit as the maximum potential misstatement amount", "The volume and nature of transactions processed by the individual and any compensating controls present", "The clerk''s tenure and employment history as a measure of trustworthiness", "Whether any actual fraudulent transactions were identified during the current audit"]'::jsonb, 1, 'AU-C 265.A10 directs the auditor to consider the volume and nature of transactions exposed to the deficiency and whether compensating controls mitigate the risk. The $2.8 million annual exposure significantly exceeds the per-transaction limit. Option D is incorrect because severity is based on what reasonably could occur, not solely on whether fraud was actually detected — absence of evidence is not evidence of absence.', 'medium', 2),

-- Q16: medium / L3 — Known, likely, and projected misstatement categories
(1, 'Misstatements and Control Deficiencies', 'During the audit of Hartwell Electronics, the engagement team compiles the following: $22,000 in specifically identified errors (known misstatements), $58,000 projected from sampling (projected misstatements), and $15,000 in differences between management''s estimates and the auditor''s estimates (judgmental misstatements). Under AU-C 450, the auditor should:', '["Only report the $22,000 in known misstatements to management because the other categories are estimates", "Sum all three categories to arrive at $95,000 and evaluate this aggregate against materiality", "Evaluate each category separately against its own materiality threshold", "Exclude the judgmental misstatements because they represent legitimate differences of opinion"]'::jsonb, 1, 'AU-C 450.05 requires the auditor to accumulate all identified misstatements — whether known, projected, or judgmental — and evaluate their aggregate effect against materiality. All three categories combine to form the total misstatement assessment. Option D is incorrect because judgmental misstatements from estimation differences are valid components of the misstatement summary and cannot be excluded simply because management disagrees.', 'medium', 3),

-- Q17: medium / L3 — Communication of deficiencies less than significant
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Lakeland Community Hospital, the auditor identifies several control deficiencies that do not rise to the level of significant deficiencies or material weaknesses. Under AU-C 265.A19, the auditor should communicate these lesser deficiencies to management:', '["Only in writing using the same format required for significant deficiencies", "Either orally or in writing, at the auditor''s discretion based on the significance and nature of the communication", "Only if specifically requested by the audit committee or board of directors", "Through inclusion in the management representation letter as an appendix"]'::jsonb, 1, 'AU-C 265.A19 permits the auditor to communicate deficiencies that are less than significant either orally or in writing. The method is at the auditor''s professional judgment. If communicated orally, the auditor should document the communication in the working papers. Option A is incorrect because the formal written communication requirement under AU-C 265.13 applies only to significant deficiencies and material weaknesses, not to lesser deficiencies.', 'medium', 3),

-- Q18: easy / L1 — Management override as inherent limitation
(1, 'Misstatements and Control Deficiencies', 'Why is management override of internal controls considered an inherent limitation when evaluating control deficiencies?', '["Because management override only occurs in companies with fewer than 100 employees", "Because no system of internal control can fully prevent deliberate circumvention by those who designed the controls", "Because management override automatically constitutes a material weakness under AU-C 265", "Because override risk is eliminated when the company has an independent audit committee"]'::jsonb, 1, 'AU-C 265.A5 acknowledges that management override is an inherent limitation of internal control because individuals with authority can circumvent controls they are responsible for implementing. This risk exists regardless of control design quality. Option C is incorrect because management override is an inherent characteristic of all control systems, not an automatically reportable material weakness — it is addressed through the auditor''s risk assessment procedures.', 'easy', 1),

-- Q19: easy / L1 — Tolerable misstatement definition
(1, 'Misstatements and Control Deficiencies', 'What is tolerable misstatement in the context of an audit engagement?', '["The maximum misstatement the auditor is willing to accept in a particular account or class of transactions", "The total dollar amount of misstatements that management has agreed to correct", "The threshold above which all misstatements must be reported to the audit committee", "The amount of misstatement that renders the financial statements fraudulent"]'::jsonb, 0, 'AU-C 530.A3 defines tolerable misstatement as the application of performance materiality to a particular sampling procedure, representing the maximum misstatement in a population the auditor can accept and still conclude the sample results support the desired audit objective. Option B is incorrect because tolerable misstatement is set by the auditor for sampling purposes, not negotiated with management for correction purposes.', 'easy', 1),

-- Q20: medium / L3 — Documentation requirements for deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Fernwood Distributors, the engagement team identifies 14 control deficiencies of varying severity. The auditor classifies three as material weaknesses, four as significant deficiencies, and seven as less-than-significant. Under AU-C 265.11, the auditor''s documentation should include:', '["Only the three material weaknesses, since documentation of lesser deficiencies is optional", "The basis for the auditor''s evaluation of each identified deficiency''s severity, including those determined to be less than significant", "A list of all 14 deficiencies without the need for severity classification rationale", "Only deficiencies that resulted in actual financial statement misstatements exceeding performance materiality"]'::jsonb, 1, 'AU-C 265.11 requires the auditor to document the basis for determining whether identified deficiencies, individually or in combination, are significant deficiencies or material weaknesses. This includes documenting why certain deficiencies were determined to be less severe. Option A is incorrect because the auditor must document the evaluation basis for all identified deficiencies, not only the most severe classifications.', 'medium', 3),

-- Q21: easy / L2 — Compensating control effect on severity
(1, 'Misstatements and Control Deficiencies', 'Brookside Automotive has no formal reconciliation of its fixed asset subledger to the general ledger. However, the controller performs a detailed quarterly review comparing asset balances to insurance schedules and property tax records. Under AU-C 265, the quarterly review functions as:', '["An alternative procedure that eliminates the need to report any control deficiency", "A compensating control that may reduce the severity of the reconciliation deficiency", "An audit procedure performed by management that replaces the auditor''s testing obligation", "A detective control that automatically converts the deficiency from material weakness to insignificant"]'::jsonb, 1, 'AU-C 265.A11 states that compensating controls can reduce the severity of a deficiency by providing alternative assurance that the relevant assertion is not materially misstated. The quarterly review partially mitigates the missing reconciliation. Option D is incorrect because compensating controls require auditor judgment about their effectiveness — they do not automatically change a deficiency''s classification.', 'easy', 2),

-- Q22: hard / L4 — Qualitative factors overriding quantitative immateriality
(1, 'Misstatements and Control Deficiencies', 'Meridian Financial Corp. has $28,000 in uncorrected misstatements against $300,000 overall materiality. However, $9,000 of the misstatements relate to transactions with a company owned by the CEO''s spouse that were not disclosed as related-party transactions. The remaining $19,000 involves routine timing differences. The auditor should:', '["Conclude all misstatements are immaterial because $28,000 is well below $300,000 materiality", "Request correction of only the $9,000 related-party amount since the remaining items are routine", "Evaluate whether the related-party misstatement and disclosure omission qualitatively render the financial statements materially misstated despite quantitative immateriality", "Report the related-party transactions to the SEC as a potential fraud indicator before completing the audit"]'::jsonb, 2, 'AU-C 450.11 requires the auditor to consider qualitative factors, including the nature of misstatements involving related parties and omitted disclosures. Undisclosed related-party transactions go to the heart of financial statement transparency and may be qualitatively material regardless of dollar amount. Option A is incorrect because a purely quantitative analysis ignores the nature of the misstatement — related-party disclosure failures carry disproportionate qualitative weight.', 'hard', 4),

-- Q23: easy / L1 — Restatement trigger
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, a misstatement discovered after the financial statements have been issued may require restatement when:', '["The misstatement is material to the previously issued financial statements", "The misstatement was caused by an employee rather than by management", "The misstatement was identified by an external party rather than by the auditor", "The misstatement involves an estimate that was reasonable at the time it was made"]'::jsonb, 0, 'AU-C 560.14 addresses subsequently discovered facts and indicates that when a misstatement is material to previously issued financial statements, the auditor should discuss the matter with management and determine whether revision is needed. Option D is incorrect because reasonable estimates do not trigger restatement — restatement applies when the original financial statements contained a material error.', 'easy', 1),

-- Q24: hard / L4 — Partially effective mitigating control evaluation
(1, 'Misstatements and Control Deficiencies', 'Atlas Energy Corp. lacks automated three-way matching for vendor invoices, which the auditor identifies as a control deficiency. Management implemented a monthly supervisory review of large payments (over $50,000) as a mitigating control. Annual vendor payments total $45 million, with 85% of transactions under $50,000. The auditor should evaluate the deficiency considering that:', '["The supervisory review fully compensates for the missing three-way match because it covers the highest-dollar transactions", "The mitigating control addresses only 15% of transaction volume, leaving the majority of payments without preventive or detective controls over accuracy", "The deficiency should be classified as insignificant because the monthly review demonstrates management''s commitment to controls", "No further evaluation is needed because vendor payment controls are not relevant to financial reporting assertions"]'::jsonb, 1, 'AU-C 265.A11 requires the auditor to assess the operating effectiveness and scope of compensating controls. Although the supervisory review covers high-dollar items, 85% of transactions lack controls over matching, creating substantial exposure. The mitigating control''s limited coverage fails to adequately reduce the deficiency''s severity. Option A is incorrect because coverage of 15% of transactions by dollar threshold does not compensate for the 85% of transactions by volume that remain uncontrolled.', 'hard', 4),

-- Q25: easy / L1 — Purpose of accumulating misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of accumulating identified misstatements during an audit?', '["To determine the fee adjustment for additional audit procedures performed", "To provide a basis for requesting a higher materiality level from those charged with governance", "To evaluate whether uncorrected misstatements are material to the financial statements as a whole", "To calculate the penalty amount that management must pay for financial reporting errors"]'::jsonb, 2, 'AU-C 450.05 requires the auditor to accumulate misstatements identified during the audit, other than those that are clearly trivial, so that the auditor can evaluate their aggregate effect on the financial statements. This evaluation determines whether the opinion should be modified. Option B is incorrect because materiality is set by the auditor using professional judgment — it is not negotiated with governance based on accumulated misstatements.', 'easy', 1),

-- Q26: easy / L1 — Written communication requirements by deficiency type
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, which control deficiency classifications require written communication to those charged with governance?', '["All identified control deficiencies regardless of their severity level", "Only material weaknesses identified during the current-year audit", "Both significant deficiencies and material weaknesses identified during the audit", "Only deficiencies that resulted in misstatements exceeding overall materiality"]'::jsonb, 2, 'AU-C 265.13 requires the auditor to communicate significant deficiencies and material weaknesses in writing to those charged with governance. Deficiencies that do not meet these thresholds may be communicated orally or in writing to management at the auditor''s discretion. Option B is incorrect because written communication to governance is required for both significant deficiencies and material weaknesses, not only material weaknesses.', 'easy', 1),

-- Q27: easy / L1 — High turnover as potential deficiency indicator
(1, 'Misstatements and Control Deficiencies', 'Frequent turnover in key accounting positions may indicate a control deficiency because:', '["High turnover automatically constitutes a material weakness under AU-C 265", "Turnover disrupts the continuity of control performance and increases the risk that controls may not operate effectively", "The auditor is required to report all staffing changes to the audit committee under AU-C 260", "New employees are prohibited from performing control activities during their first year"]'::jsonb, 1, 'AU-C 265.A6 recognizes that the competence and continuity of personnel performing control activities affect control effectiveness. High turnover may result in controls not operating as designed during transition periods, increasing the risk of undetected errors. Option A is incorrect because turnover alone is not an automatic material weakness — the auditor must evaluate the actual impact on control performance and the presence of mitigating factors.', 'easy', 1),

-- Q28: hard / L4 — Repeated material weakness and governance response
(1, 'Misstatements and Control Deficiencies', 'Brighton Healthcare reported a material weakness in revenue recognition controls to its audit committee in 2024 and 2025. The audit committee acknowledged the communications but took no remedial action. For the 2026 audit, the auditor again identifies the same material weakness. The auditor should:', '["Decline to issue the written communication because it would be redundant with prior-year letters", "Withdraw from the engagement because the audit committee''s inaction indicates a governance failure", "Communicate the material weakness in writing again and consider the implications for risk assessment, audit strategy, and the control environment", "Downgrade the classification to significant deficiency because it has already been communicated twice"]'::jsonb, 2, 'AU-C 265.A18 states that the auditor should communicate material weaknesses each year they exist, even if previously communicated. The audit committee''s repeated inaction may signal broader control environment issues that affect the auditor''s risk assessment. Option A is incorrect because recurring material weaknesses must be re-communicated each year — prior communications do not satisfy the current-year obligation.', 'hard', 4),

-- Q29: medium / L3 — Relevance of corrected misstatements to audit conclusions
(1, 'Misstatements and Control Deficiencies', 'During the audit of Orchard Valley Foods, management corrected all 12 misstatements identified by the auditor, totaling $175,000 against materiality of $200,000. After correction, the engagement partner should consider whether the volume and magnitude of corrected misstatements:', '["Are irrelevant because the financial statements now reflect correct amounts", "Indicate possible additional undetected misstatements that could warrant expanded procedures", "Must be reported to the audit committee as if they were uncorrected misstatements", "Require the auditor to issue a qualified opinion due to the original existence of the errors"]'::jsonb, 1, 'AU-C 450.08 requires the auditor to consider the nature and circumstances of misstatements, including corrected ones, in determining whether additional audit procedures are needed. A large volume of corrected misstatements near materiality may indicate systemic issues and undetected errors elsewhere. Option A is incorrect because corrected misstatements remain relevant to the auditor''s assessment of internal control effectiveness and the risk of undetected misstatements.', 'medium', 3),

-- Q30: medium / L2 — Management representation about uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'After finalizing the summary of uncorrected misstatements for the audit of Cedar Ridge Properties, the auditor attaches the list to the management representation letter. Under AU-C 580, management''s representation regarding uncorrected misstatements should state that:', '["Management will correct all listed misstatements in the subsequent reporting period", "The auditor is responsible for determining the materiality of the uncorrected misstatements", "Management believes the effects of the uncorrected misstatements are immaterial individually and in the aggregate to the financial statements as a whole", "Management disagrees with the auditor''s identification of the items as misstatements"]'::jsonb, 2, 'AU-C 580.16 requires management to represent in the written representation letter that it believes the effects of uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements taken as a whole. A summary of these items is appended. Option A is incorrect because the representation concerns the current-period materiality judgment, not a promise to correct the items in a future period.', 'medium', 2)
;

COMMIT;
